"use strict";(globalThis.webpackChunkgrc||=[]).push([[35610],{51631(e){e.exports=JSON.parse('{"citeKey":"he2003qosguided","slug":"he-2003-qos-guided-cd3b","title":"QoS Guided Min-Min Heuristic for Grid Task Scheduling","authors":["X. He","X.-H. Sun","G. Laszewski"],"venue":"Journal of Computer Science and Technology, Special Issue on Grid Computing, 18(4)","type":"Journal","entryType":"article","date":"January, 2003","year":2003,"era":"iit","month":1,"doi":"10.1007/bf02948918","abstract":"Task scheduling is an integrated component of computing. With the emergence of Grid and ubiquitous computing, new challenges appear in task scheduling based on properties such as security, quality of service, and lack of central control within distributed administrative domains. A Grid task scheduling framework must be able to deal with these issues. One of the goals of Grid task scheduling is to achieve high system throughput while matching application needs with the available computing resources. This matching of resources in a non-deterministically shared heterogeneous environment leads to concerns over Quality of Service (QoS). In this paper we introduce a novel QoS guided task scheduling algorithm for Grid computing. Our novel algorithm is based on a general adaptive scheduling heuristics that includes QoS guidance. We evaluate our algorithm within a simulated Grid environment. These experimental results show that the new QoS guided Min-Min heuristic can lead to significant performance gain for a variety of applications. We compare our approach to others based on the quality of the prediction formulated by inaccurate information.","hasAbstract":true,"lede":"A Grid task scheduling framework must be able to deal with these issues.","links":{"pdf":"https://grc.iit.edu/papers/2003/he-2003-qos-guided-cd3b.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":["ghs"],"memberAuthors":["sun-xian-he"]}')}}]);